select json_build_object(
'tables',(select json_agg(json_build_object('key',n.nspname||'.'||c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','phron_private') and c.relkind='r'),
'columns',(select json_agg(json_build_object('key',table_schema||'.'||table_name||'.'||column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'default',column_default) order by table_schema,table_name,ordinal_position) from information_schema.columns where table_schema in ('public','phron_private')),
'constraints',(select json_agg(json_build_object('key',n.nspname||'.'||c.relname||'.'||x.conname,'definition',pg_get_constraintdef(x.oid,true)) order by n.nspname,c.relname,x.conname) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','phron_private')),
'policies',(select json_agg(json_build_object('key',schemaname||'.'||tablename||'.'||policyname,'command',cmd,'roles',roles,'using',qual,'with_check',with_check) order by schemaname,tablename,policyname) from pg_policies where schemaname in ('public','phron_private')),
'routines',(select json_agg(json_build_object('key',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','definition_md5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','phron_private') and p.prokind='f'),
'triggers',(select json_agg(json_build_object('key',n.nspname||'.'||c.relname||'.'||t.tgname,'definition',pg_get_triggerdef(t.oid,true)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','phron_private')),
'grants',(select json_agg(json_build_object('key',table_schema||'.'||table_name||'.'||grantee||'.'||privilege_type,'grantable',is_grantable) order by table_schema,table_name,grantee,privilege_type) from information_schema.role_table_grants where table_schema in ('public','phron_private')),
'indexes',(select json_agg(json_build_object('key',schemaname||'.'||tablename||'.'||indexname,'definition',indexdef) order by schemaname,tablename,indexname) from pg_indexes where schemaname in ('public','phron_private'))
) as catalog;
